function query() {
  const timestamp = Math.floor(Date.now() / 1000);
  return {
    timestamp,
    url: "https://api.wheretheiss.at/v1/satellites/25544/positions?timestamps=" + timestamp,
  };
}

return [{ json: query() }];

function row({ body, timestamp }) {
  if (!Array.isArray(body) || body.length !== 1) throw Error("Expected one ISS position");
  const p = body[0];
  if (
    !p ||
    p.id !== 25544 ||
    typeof p.name !== "string" ||
    !p.name ||
    !Number.isFinite(p.latitude) ||
    p.latitude < -90 ||
    p.latitude > 90 ||
    !Number.isFinite(p.longitude) ||
    p.longitude < -180 ||
    p.longitude > 180 ||
    p.timestamp !== timestamp
  )
    throw Error("ISS position does not match the request");
  const position = {
    name: p.name,
    latitude: p.latitude,
    longitude: p.longitude,
    timestamp: p.timestamp,
  };
  return { position, rows: [{ json: position }] };
}

const p = row({
  body: $input.first().json,
  timestamp: $("Prepare the current timestamp").first().json.timestamp,
}).position;
return [{ json: { timestamp: p.timestamp, latitude: p.latitude, longitude: p.longitude } }];

const items = $input.all(),
  data = $getWorkflowStaticData("node");
data.timestamp = data.timestamp || [];
const p = items[0].json,
  duplicate = data.timestamp.includes(p.timestamp);
data.timestamp = items.map((x) => x.json.timestamp);
return duplicate ? [{ json: { message: "No new items" } }] : items;
